-- S.I.P.E.C — Schéma complet Supabase
create extension if not exists pgcrypto;
do $$ begin create type sipec_role as enum ('super_admin','media_admin','pastor','editor'); exception when duplicate_object then null; end $$;
do $$ begin create type publish_status as enum ('draft','published','archived'); exception when duplicate_object then null; end $$;
do $$ begin create type media_type as enum ('photo','video'); exception when duplicate_object then null; end $$;
do $$ begin create type stream_status as enum ('live','offline','replay','scheduled'); exception when duplicate_object then null; end $$;

create table if not exists public.settings (id uuid primary key default gen_random_uuid(), church_name text not null, slogan_fr text, slogan_en text, slogan_sw text, logo_url text, phone text, whatsapp text, email text, address_fr text, address_en text, address_sw text, city text, country text, google_maps_url text, gps_lat double precision, gps_lng double precision, facebook_url text, youtube_url text, instagram_url text, tiktok_url text, twitter_url text, general jsonb not null default '{}'::jsonb, status publish_status not null default 'published', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.hero (id uuid primary key default gen_random_uuid(), title_fr text not null, title_en text, title_sw text, subtitle_fr text, subtitle_en text, subtitle_sw text, image_url text, scripture_reference text, scripture_text_fr text, scripture_text_en text, scripture_text_sw text, primary_button_label jsonb default '{}', primary_button_url text, secondary_button_label jsonb default '{}', secondary_button_url text, status publish_status not null default 'published', sort_order integer default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.about (id uuid primary key default gen_random_uuid(), mission_fr text, mission_en text, mission_sw text, vision_fr text, vision_en text, vision_sw text, history_fr text, history_en text, history_sw text, status publish_status not null default 'published', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.founder (id uuid primary key default gen_random_uuid(), name text, title_fr text, title_en text, title_sw text, photo_url text, biography_fr text, biography_en text, biography_sw text, vision_fr text, vision_en text, vision_sw text, quote_fr text, quote_en text, quote_sw text, status publish_status not null default 'published', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.departments (id uuid primary key default gen_random_uuid(), name_fr text not null, name_en text, name_sw text, badge_fr text, badge_en text, badge_sw text, image_url text, description_fr text, description_en text, description_sw text, schedule_fr text, schedule_en text, schedule_sw text, status publish_status not null default 'published', sort_order integer default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.choirs (id uuid primary key default gen_random_uuid(), name_fr text not null, name_en text, name_sw text, photo_url text, description_fr text, description_en text, description_sw text, schedule_fr text, schedule_en text, schedule_sw text, status publish_status not null default 'published', sort_order integer default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.gallery_albums (id uuid primary key default gen_random_uuid(), title_fr text not null, title_en text, title_sw text, description_fr text, description_en text, description_sw text, cover_image text, status publish_status not null default 'published', sort_order integer default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.gallery_media (id uuid primary key default gen_random_uuid(), album_id uuid references public.gallery_albums(id) on delete set null, type media_type not null, photo_url text, video_url text, thumbnail_url text, title_fr text, title_en text, title_sw text, description_fr text, description_en text, description_sw text, media_date date, status publish_status not null default 'published', sort_order integer default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.sermons (id uuid primary key default gen_random_uuid(), title_fr text not null, title_en text, title_sw text, bible_reference text, preacher_fr text, preacher_en text, preacher_sw text, description_fr text, description_en text, description_sw text, video_url text, audio_url text, thumbnail_url text, duration text, published_at timestamptz, category_fr text, category_en text, category_sw text, downloads integer default 0, featured boolean default false, status publish_status not null default 'draft', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.livestreams (id uuid primary key default gen_random_uuid(), title_fr text not null, title_en text, title_sw text, description_fr text, description_en text, description_sw text, youtube_url text, facebook_url text, tiktok_url text, instagram_url text, is_live boolean default false, start_time timestamptz, end_time timestamptz, thumbnail_url text, status stream_status default 'offline', viewers integer default 0, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.events (id uuid primary key default gen_random_uuid(), title_fr text not null, title_en text, title_sw text, description_fr text, description_en text, description_sw text, image_url text, event_date timestamptz, location_fr text, location_en text, location_sw text, status publish_status not null default 'draft', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.contacts (id uuid primary key default gen_random_uuid(), address_fr text, address_en text, address_sw text, phone text, whatsapp text, email text, google_maps_url text, gps_lat double precision, gps_lng double precision, status publish_status not null default 'published', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text, full_name text, role sipec_role not null default 'editor', active boolean not null default true, created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.media (id uuid primary key default gen_random_uuid(), title text, type text, url text, thumbnail text, album text, description text, status text default 'published', created_at timestamptz default now(), updated_at timestamptz default now());
create table if not exists public.prayer_requests (id uuid primary key default gen_random_uuid(), full_name text not null, email_or_phone text, request_text text not null, is_urgent boolean default false, is_private boolean default true, status text default 'pending', created_at timestamptz default now(), updated_at timestamptz default now());

-- Migrations non destructives pour les bases créées avant l'ajout des colonnes FR/EN/SW.
alter table public.settings add column if not exists status publish_status not null default 'published', add column if not exists created_at timestamptz default now(), add column if not exists updated_at timestamptz default now();
alter table public.hero add column if not exists primary_button_label jsonb default '{}'::jsonb, add column if not exists secondary_button_label jsonb default '{}'::jsonb, add column if not exists status publish_status not null default 'published', add column if not exists sort_order integer default 0, add column if not exists updated_at timestamptz default now();
alter table public.about add column if not exists status publish_status not null default 'published', add column if not exists updated_at timestamptz default now();
alter table public.founder add column if not exists quote_fr text, add column if not exists quote_en text, add column if not exists quote_sw text, add column if not exists status publish_status not null default 'published', add column if not exists updated_at timestamptz default now();
alter table public.departments add column if not exists updated_at timestamptz default now();
alter table public.choirs add column if not exists updated_at timestamptz default now();
alter table public.gallery_albums add column if not exists updated_at timestamptz default now();
alter table public.gallery_media add column if not exists title_fr text, add column if not exists title_en text, add column if not exists title_sw text, add column if not exists updated_at timestamptz default now();
alter table public.sermons add column if not exists updated_at timestamptz default now();
alter table public.livestreams add column if not exists updated_at timestamptz default now();
alter table public.events add column if not exists updated_at timestamptz default now();
alter table public.contacts add column if not exists updated_at timestamptz default now();
alter table public.profiles add column if not exists updated_at timestamptz default now();

create index if not exists idx_departments_status on public.departments(status); create index if not exists idx_gallery_media_album on public.gallery_media(album_id); create index if not exists idx_gallery_media_status on public.gallery_media(status); create index if not exists idx_sermons_status on public.sermons(status); create index if not exists idx_sermons_published on public.sermons(published_at desc); create index if not exists idx_livestreams_status on public.livestreams(status); create index if not exists idx_events_date on public.events(event_date); create index if not exists idx_events_status on public.events(status);

create or replace function public.handle_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now(); return new; end; $$;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['settings','hero','about','founder','departments','choirs','gallery_albums','gallery_media','sermons','livestreams','events','contacts','profiles','media','prayer_requests'] LOOP EXECUTE format('drop trigger if exists set_updated_at on public.%I; create trigger set_updated_at before update on public.%I for each row execute function public.handle_updated_at()',t,t); END LOOP; END $$;

alter table public.settings enable row level security; alter table public.hero enable row level security; alter table public.about enable row level security; alter table public.founder enable row level security; alter table public.departments enable row level security; alter table public.choirs enable row level security; alter table public.gallery_albums enable row level security; alter table public.gallery_media enable row level security; alter table public.sermons enable row level security; alter table public.livestreams enable row level security; alter table public.events enable row level security; alter table public.contacts enable row level security; alter table public.profiles enable row level security; alter table public.media enable row level security; alter table public.prayer_requests enable row level security;

create or replace function public.current_sipec_role() returns sipec_role language sql stable security definer as $$ select role from public.profiles where id=auth.uid() and active=true; $$;
create or replace function public.is_sipec_admin() returns boolean language sql stable security definer as $$ select exists(select 1 from public.profiles where id=auth.uid() and active=true); $$;

DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['settings','hero','about','founder','departments','choirs','gallery_albums','gallery_media','sermons','events','contacts'] LOOP EXECUTE format('drop policy if exists "public read %s" on public.%I; create policy "public read %s" on public.%I for select using (status=''published'')',t,t,t,t); EXECUTE format('drop policy if exists "admin manage %s" on public.%I; create policy "admin manage %s" on public.%I for all using (public.is_sipec_admin()) with check (public.is_sipec_admin())',t,t,t,t); END LOOP; END $$;
drop policy if exists "public read livestreams" on public.livestreams; create policy "public read livestreams" on public.livestreams for select using (true);
drop policy if exists "admin manage livestreams" on public.livestreams; create policy "admin manage livestreams" on public.livestreams for all using (public.is_sipec_admin()) with check (public.is_sipec_admin());
drop policy if exists "public media read" on public.media; create policy "public media read" on public.media for select using (status='published');
drop policy if exists "admin media manage" on public.media; create policy "admin media manage" on public.media for all using (public.is_sipec_admin()) with check (public.is_sipec_admin());
drop policy if exists "public prayer insert" on public.prayer_requests; create policy "public prayer insert" on public.prayer_requests for insert with check (true);
drop policy if exists "admin prayer manage" on public.prayer_requests; create policy "admin prayer manage" on public.prayer_requests for all using (public.is_sipec_admin()) with check (public.is_sipec_admin());
drop policy if exists "own profile read" on public.profiles; create policy "own profile read" on public.profiles for select using (auth.uid()=id or public.current_sipec_role()='super_admin');
drop policy if exists "super admin manage profiles" on public.profiles; create policy "super admin manage profiles" on public.profiles for all using (public.current_sipec_role()='super_admin') with check (public.current_sipec_role()='super_admin');

create or replace function public.create_profile_on_signup() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,email,full_name,role) values(new.id,new.email,coalesce(new.raw_user_meta_data->>'full_name',new.email),'editor') on conflict(id) do update set email=excluded.email; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.create_profile_on_signup();

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('hero-images','hero-images',true,20971520,array['image/jpeg','image/png','image/webp']),('departments','departments',true,20971520,array['image/jpeg','image/png','image/webp']),('choirs','choirs',true,20971520,array['image/jpeg','image/png','image/webp']),('gallery','gallery',true,104857600,array['image/jpeg','image/png','image/webp','video/mp4','video/webm']),('sermons','sermons',true,1073741824,array['image/jpeg','image/png','image/webp','video/mp4','audio/mpeg','audio/mp4']),('livestreams','livestreams',true,20971520,array['image/jpeg','image/png','image/webp']),('events','events',true,20971520,array['image/jpeg','image/png','image/webp']),('founder','founder',true,20971520,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;

drop policy if exists "public storage read" on storage.objects; create policy "public storage read" on storage.objects for select using (bucket_id in ('hero-images','departments','choirs','gallery','sermons','livestreams','events','founder'));
drop policy if exists "admin storage insert" on storage.objects; create policy "admin storage insert" on storage.objects for insert with check (bucket_id in ('hero-images','departments','choirs','gallery','sermons','livestreams','events','founder') and public.is_sipec_admin());
drop policy if exists "admin storage update" on storage.objects; create policy "admin storage update" on storage.objects for update using (bucket_id in ('hero-images','departments','choirs','gallery','sermons','livestreams','events','founder') and public.is_sipec_admin());
drop policy if exists "admin storage delete" on storage.objects; create policy "admin storage delete" on storage.objects for delete using (bucket_id in ('hero-images','departments','choirs','gallery','sermons','livestreams','events','founder') and public.is_sipec_admin());

-- Realtime : changements visibles immédiatement sur le site public
do $$
declare realtime_table text;
begin
  foreach realtime_table in array array['settings','hero','about','founder','departments','choirs','gallery_albums','gallery_media','sermons','livestreams','events','contacts','media'] loop
    if not exists (select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=realtime_table) then
      execute format('alter publication supabase_realtime add table public.%I', realtime_table);
    end if;
  end loop;
end $$;
